import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonSlurper

Message processData(Message message) {
    def json = new JsonSlurper().parse(message.getBody(Reader))
    def score = json.assessment.score
    if (!score) {
        throw new IllegalStateException("Assessment score missing for ${json.applicationId}")
    }
    message.setHeader('assessmentScore', score)
    return message
}

import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonSlurper

Message processData(Message message) {
    // OData V2 response: { "d": { "results": [ ... ] } }
    def json = new JsonSlurper().parse(message.getBody(Reader))
    def status = json.d.results.status
    if (status == 'Hired') {
        message.setProperty('route', 'payroll')
    } else {
        message.setProperty('route', 'archive')
    }
    return message
}

import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonSlurper

Message processData(Message message) {
    def apps = new JsonSlurper().parse(message.getBody(Reader))
    Map<String, String> statusById = new HashMap<>()
    apps.each { app -> statusById.put("A-${app.id}", app.status) }

    String key = message.getProperty('applicationId')   // 'A-1001'
    message.setProperty('status', statusById.get(key))
    message.setProperty('known', statusById.keySet().join(','))
    return message
}

import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonSlurper

String acceptedOfferId(List offers) {
    offers.each { offer ->
        if (offer.status == 'Accepted') {
            return offer.id
        }
    }
    return null
}

Message processData(Message message) {
    def offers = new JsonSlurper().parse(message.getBody(Reader)).offers
    message.setProperty('offerId', acceptedOfferId(offers))
    return message
}

import com.sap.gateway.ip.core.customdev.util.Message
import groovy.json.JsonSlurper

Message processData(Message message) {
    Long expected = message.getProperty('expectedCount') as Long
    def json = new JsonSlurper().parse(message.getBody(Reader))
    def actual = json.applications.size()
    if (!actual.equals(expected)) {
        throw new IllegalStateException("Expected ${expected} applications, got ${actual}")
    }
    return message
}

import com.sap.gateway.ip.core.customdev.util.Message
import groovy.xml.XmlSlurper
import groovy.xml.XmlUtil

Message processData(Message message) {
    def root = new XmlSlurper().parse(message.getBody(Reader))
    root.JobApplication.each { app ->
        if (!app.source.size()) {
            app.appendNode { source('JobBoard') }
        }
    }
    def missing = root.JobApplication.count { it.source.text() == '' }
    if (missing) {
        throw new IllegalStateException("${missing} applications without a source")
    }
    message.setBody(XmlUtil.serialize(root))
    return message
}

